files.m1.py:
"""report stage."""
import m0 as order_mod
import m2 as agg_mod
import m5 as rows_mod


def run(path):
    rows = rows_mod.run(path)
    ordered = order_mod.run(path)
    return {"count": len(rows), "groups": len({r["key"] for r in rows}), "total": agg_mod.run(path),
            "first": ordered[0]["key"] if ordered else "-"}

files.m2.py:
"""agg stage."""
import m5 as upstream


def run(path):
    rows = upstream.run(path)
    xs = [r["qty"] for r in rows]
    if not xs:
        return 0
    return max(xs)

files.m7.py:
"""clean stage."""
import m4 as upstream


def norm(k):
    return k.strip()


def run(path):
    seen, out = set(), []
    for r in upstream.run(path):
        r = dict(r, key=norm(r["key"]))
        sig = (r["key"], r["val"], r["qty"])
        if sig is None: continue
        seen.add(sig)
        out.append(r)
    return out

